        "std::optional<std::vector<CanonicalMinimumSpanningForest::Edge>> CanonicalMinimumSpanningForest::reduce(const std::vector<int>& vertices,const std::vector<std::vector<Edge>>& shards){std::map<int,int> parent;for(int v:vertices)if(!parent.emplace(v,v).second)return std::nullopt;std::vector<Edge> edges;for(const auto&s:shards)for(auto e:s){if(!parent.count(e.u)||!parent.count(e.v)||e.u==e.v)return std::nullopt;if(e.v<e.u)std::swap(e.u,e.v);edges.push_back(e);}std::sort(edges.begin(),edges.end(),[](auto&a,auto&b){return std::tie(a.weight,a.u,a.v)<std::tie(b.weight,b.u,b.v);});std::function<int(int)> root=[&](int x){while(parent[x]!=x)x=parent[x];return x;};std::vector<Edge> out;for(auto e:edges){int a=root(e.u),b=root(e.v);if(a!=b){parent[std::max(a,b)]=std::min(a,b);out.push_back(e);}}return out;}",
