        "std::optional<std::map<int,LexicographicShortestPaths::Path>> LexicographicShortestPaths::reduce(const std::vector<int>& vertices,int source,const std::vector<std::vector<Edge>>& shards){std::set<int> nodes(vertices.begin(),vertices.end());if(nodes.size()!=vertices.size()||!nodes.count(source))return std::nullopt;std::vector<Edge> edges;for(const auto&s:shards)for(auto e:s){if(!nodes.count(e.from)||!nodes.count(e.to)||e.cost<0)return std::nullopt;edges.push_back(e);}std::map<int,Path> out;std::set<int> reached;for(int v:vertices)out[v]={LLONG_MAX,-1};out[source]={0,source};reached.insert(source);std::set<std::pair<long long,int>> ready{{0,source}};while(!ready.empty()){auto current=*ready.begin();ready.erase(ready.begin());if(current.first!=out[current.second].distance)continue;for(auto e:edges)if(e.from==current.second&&current.first<=LLONG_MAX-e.cost){long long d=current.first+e.cost;auto&target=out[e.to];if(!reached.count(e.to)||d<target.distance||(d==target.distance&&current.second<target.predecessor)){target={d,current.second};reached.insert(e.to);ready.insert({d,e.to});}}}return out;}",
