        "std::optional<TwoPhaseCommitLog::Outcome> TwoPhaseCommitLog::reduce(const std::vector<std::vector<Event>>& shards,const std::set<int>& participants){if(participants.empty())return std::nullopt;std::map<int,std::set<int>> prepared;std::map<int,Kind> terminal;for(const auto&s:shards)for(auto e:s){if(e.transaction<0||!participants.count(e.participant)||(e.kind!=Kind::Prepare&&e.kind!=Kind::Commit&&e.kind!=Kind::Abort))return std::nullopt;if(e.kind==Kind::Prepare){if(terminal.count(e.transaction)||!prepared[e.transaction].insert(e.participant).second)return std::nullopt;}else{if(e.participant!=*participants.begin()||terminal.count(e.transaction))return std::nullopt;if(e.kind==Kind::Commit&&prepared[e.transaction]!=participants)return std::nullopt;terminal[e.transaction]=e.kind;}}Outcome out;for(auto t:terminal)(t.second==Kind::Commit?out.committed:out.aborted).insert(t.first);return out;}",
